public TestRequest convertJsonReqToJavaObject(String jsonRequestString) {
	//logger.info("Inside convertJsonReqToJavaObject of TestController jsonRequestString:{}", jsonRequestString);
	ObjectMapper objectMapper = new ObjectMapper();
	TestRequest testRequest = null;
	try {
		testRequest = objectMapper.readValue(jsonRequestString, TestRequest.class);
	} catch (JsonProcessingException e) {
		logger.error("Error converting JSON to TestRequest object", e.getMessage());
	}
	return testRequest;
}
